from anim_lib import *

BLUR = "concat.gaussian-blur"
WIPE = "concat.reveal-wipe"
WORDS = "concat.reveal-words"

def ti(slug, name, order, desc, **kw):
    return A("text-in-" + slug, name, "in", order, desc, text=True, **kw)

def wipe(direction, soft=20):
    return (WIPE, {"progress": "100 * t", "direction": str(direction), "softness": str(soft)})

def words(soft=0):
    return (WORDS, {"progress": "100 * t", "softness": str(soft)})

def blur(k=30):
    return (BLUR, {"radius": f"1 + {k} * (1 - t)"})

