tin = {s["slug"]: s for s in TEXT_INS}

def to(slug, name, order, desc, source):
    return out_of(tin["text-in-" + source], "text-out-" + slug, name, order, desc)

def tout(slug, name, order, desc, **kw):
    return A("text-out-" + slug, name, "out", order, desc, text=True, **kw)

